#include "sim.h"
#include <stdio.h>
#include <math.h>
#include <assert.h>
int main(){for(int tow=0;tow<2;tow++)for(int reverse=0;reverse<2;reverse++){Game g;rh_new_game(&g);g.traffic_count=0;g.traffic_t=-1e9;g.job.stage=tow;float z=reverse?7800:6600;rh_set_player(&g,rh_road_x(0,z),z,0);g.player.reverse=reverse;Controls c={0};if(reverse)c.brake=1;else c.throttle=1;for(int i=0;i<60000;i++){float target=rh_road_x(0,g.player.z+20*(reverse?-1:1));float deriv=(rh_road_x(0,g.player.z+2)-rh_road_x(0,g.player.z-2))/4;float err=target-g.player.x; c.steer=fmaxf(-1,fminf(1,(atanf(deriv)-g.player.yaw)*3+err*.02*(reverse?-1:1))); if(reverse && tow){ float terr=rh_road_x(0,g.player.trailer_z-30)-g.player.trailer_x; float trailer_target=atan2f(-terr,30); float cab_target=3*g.player.trailer_yaw-2*trailer_target; c.steer=fmaxf(-1,fminf(1,(cab_target-g.player.yaw)*3)); } if(reverse)c.steer=-c.steer;rh_step(&g,c,1.f/60);if((!reverse&&g.player.z>7780)||(reverse&&g.player.z<6620))break;}assert((!reverse&&g.player.z>7780)||(reverse&&g.player.z<6620));assert(g.player.damage<.01f);assert(g.player.road_level==0);printf("tow %d reverse %d z %.1f x %.1f v %.1f damage %.1f level %d\n",tow,reverse,g.player.z,g.player.x,g.player.v,g.player.damage,g.player.road_level);printf("yaw %.3f trailer %.3f tx %.2f tz %.2f\n",g.player.yaw,g.player.trailer_yaw,g.player.trailer_x,g.player.trailer_z);printf("road %.3f trailer road %.3f\n",rh_road_x(0,g.player.z),rh_road_x(0,g.player.trailer_z));} }
